  --radius: .75rem; /* 12px */
  --shadow-2xs: 0px 1px 2px 0px hsl(240 10% 10% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(240 10% 10% / 0.08);
  --shadow-sm: 0px 2px 4px 0px hsl(240 10% 10% / 0.06), 0px 1px 2px -1px hsl(240 10% 10% / 0.04);
  --shadow: 0px 4px 6px -1px hsl(240 10% 10% / 0.08), 0px 2px 4px -2px hsl(240 10% 10% / 0.05);
  --shadow-md: 0px 6px 8px -2px hsl(240 10% 10% / 0.10), 0px 4px 6px -2px hsl(240 10% 10% / 0.06);
  --shadow-lg: 0px 10px 15px -3px hsl(240 10% 10% / 0.12), 0px 4px 6px -4px hsl(240 10% 10% / 0.08);
  --shadow-xl: 0px 20px 25px -5px hsl(240 10% 10% / 0.15), 0px 8px 10px -6px hsl(240 10% 10% / 0.10);
  --shadow-2xl: 0px 25px 50px -12px hsl(240 10% 10% / 0.20);
  --tracking-normal: 0em;
