  // Don't render if not authenticated
  if (localStorage.getItem("admin_registered") !== "true") {
    return null;
  }

  const [selectedTab, setSelectedTab] = useState("kyc");
  const [showRejectDialog, setShowRejectDialog] = useState(false);
