      {showIncomingCall && randomMatchedCreator && (
        <IncomingCallModal
          callerName={randomMatchedCreator.name}
          pricePerMinute={25}
          onAccept={() => {
            setShowIncomingCall(false);
            setLocation(`/user/call/${randomMatchedCreator.id}`);
          }}
          onReject={() => {
            setShowIncomingCall(false);
            setRandomMatchedCreator(null);
          }}
        />
      )}
    </div>
  );
}

