                        maxLength={6}
                        className="pl-10"
                        data-testid="input-otp-agent"
                      />
                    </div>
                  </div>

                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      onClick={() => {
                        setShowOTP(false);
                        setOtp("");
                      }}
                      className="flex-1"
                      data-testid="button-change-number"
                    >
                      Change Number
                    </Button>
                    <Button
                      className="flex-1"
                      onClick={handleLogin}
                      data-testid="button-verify-otp-agent"
                    >
                      Verify & Login
                    </Button>
                  </div>

                  <Button
