              variant="outline"
              className="w-full"
              onClick={() => setLocation("/creator/login")}
              data-testid="button-switch-to-creator"
            >
              Login as Creator instead
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

