}

client/src/pages/CreatorOnboarding.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { ThemeToggle } from "@/components/ThemeToggle";
import { User, CreditCard, FileText, Gift, CheckCircle2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export default function CreatorOnboarding() {
  const [location, setLocation] = useLocation();
  const { toast } = useToast();
  const [step, setStep] = useState(1);

  // Determine role based on current URL
  const role = location.includes("/agent/") ? "agent" : "creator";

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    bankAccountNumber: "",
    bankIfscCode: "",
    bankAccountName: "",
    aadharNumber: "",
    panNumber: "",
    referralCode: "",
  });

  const updateField = (field: string, value: string) => {
    setFormData({ ...formData, [field]: value });
  };

  const handleNext = () => {
    // Validation for current step
    if (step === 1 && (!formData.name || formData.name.length < 3)) {
      toast({
        title: "Invalid Name",
        description: "Please enter your full name (minimum 3 characters)",
        variant: "destructive",
      });
      return;
    }

    if (step === 2) {
      if (!formData.bankAccountNumber || !formData.bankIfscCode || !formData.bankAccountName) {
        toast({
          title: "Incomplete Bank Details",
          description: "Please fill in all bank details",
          variant: "destructive",
        });
        return;
      }
    }

    if (step === 3) {
      if (!formData.aadharNumber || !formData.panNumber) {
        toast({
          title: "Incomplete KYC Details",
          description: "Please provide both Aadhar and PAN numbers",
          variant: "destructive",
        });
        return;
      }
    }

    if (step < 4) {
      setStep(step + 1);
    } else {
      handleSubmit();
    }
  };

  const handleSubmit = () => {
    // Store registration data based on role
    if (role === "creator") {
      localStorage.setItem("creator_registered", "true");
      localStorage.setItem("creator_approval_status", "pending");
    } else {
      localStorage.setItem("agent_registered", "true");
      localStorage.setItem("agent_approval_status", "pending");
    }

    toast({
      title: "Registration Submitted",
      description: "Your profile is under review. You'll be notified once approved.",
    });

    setTimeout(() => {
      setLocation(role === "creator" ? "/creator/pending-approval" : "/agent/pending-approval");
    }, 1500);
  };

  const progressPercentage = (step / 4) * 100;

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <div className="absolute top-4 right-4">
        <ThemeToggle />
      </div>

      <div className="w-full max-w-2xl">
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between mb-4">
              <CardTitle>{role === "creator" ? "Creator" : "Agent"} Registration</CardTitle>
              <span className="text-sm text-muted-foreground">Step {step} of 4</span>
            </div>
            <Progress value={progressPercentage} className="h-2" />
          </CardHeader>

          <CardContent className="space-y-6">
            {/* Step 1: Personal Information */}
            {step === 1 && (
              <div className="space-y-4">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center">
                    <User className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg">Personal Information</h3>
                    <p className="text-sm text-muted-foreground">Let's start with your basic details</p>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="name">Full Name *</Label>
                  <Input
                    id="name"
                    placeholder="Enter your full name"
                    value={formData.name}
                    onChange={(e) => updateField("name", e.target.value)}
                    data-testid="input-name"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="email">Email (Optional)</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="Enter your email"
                    value={formData.email}
                    onChange={(e) => updateField("email", e.target.value)}
                    data-testid="input-email"
                  />
                  <p className="text-xs text-muted-foreground">
                    Used for important notifications only
                  </p>
                </div>
              </div>
            )}

            {/* Step 2: Bank Details */}
            {step === 2 && (
              <div className="space-y-4">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center">
                    <CreditCard className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg">Bank Account Details</h3>
                    <p className="text-sm text-muted-foreground">For receiving your earnings</p>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="bankAccountName">Account Holder Name *</Label>
                  <Input
                    id="bankAccountName"
                    placeholder="Name as per bank account"
                    value={formData.bankAccountName}
                    onChange={(e) => updateField("bankAccountName", e.target.value)}
                    data-testid="input-bank-account-name"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="bankAccountNumber">Account Number *</Label>
                  <Input
                    id="bankAccountNumber"
                    placeholder="Enter account number"
                    value={formData.bankAccountNumber}
                    onChange={(e) => updateField("bankAccountNumber", e.target.value)}
                    data-testid="input-bank-account-number"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="bankIfscCode">IFSC Code *</Label>
                  <Input
                    id="bankIfscCode"
                    placeholder="Enter IFSC code"
                    value={formData.bankIfscCode}
                    onChange={(e) => updateField("bankIfscCode", e.target.value.toUpperCase())}
                    data-testid="input-bank-ifsc"
                  />
                </div>
              </div>
            )}

            {/* Step 3: KYC Documents */}
            {step === 3 && (
              <div className="space-y-4">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center">
                    <FileText className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg">KYC Documents</h3>
                    <p className="text-sm text-muted-foreground">Required for verification</p>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="aadharNumber">Aadhar Number *</Label>
                  <Input
                    id="aadharNumber"
                    placeholder="Enter 12-digit Aadhar number"
                    value={formData.aadharNumber}
                    onChange={(e) => updateField("aadharNumber", e.target.value.replace(/\D/g, "").slice(0, 12))}
                    maxLength={12}
                    data-testid="input-aadhar"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="panNumber">PAN Number *</Label>
                  <Input
                    id="panNumber"
                    placeholder="Enter PAN number"
                    value={formData.panNumber}
                    onChange={(e) => updateField("panNumber", e.target.value.toUpperCase().slice(0, 10))}
                    maxLength={10}
                    data-testid="input-pan"
                  />
                </div>

                <div className="bg-amber-500/10 border border-amber-500/20 rounded-lg p-4">
                  <p className="text-sm">
                    <strong>Note:</strong> Your documents will be verified by our admin team. 
                    This process usually takes 24-48 hours.
                  </p>
                </div>
              </div>
            )}

            {/* Step 4: Referral Code */}
            {step === 4 && (
              <div className="space-y-4">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center">
                    <Gift className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg">Referral Code (Optional)</h3>
                    <p className="text-sm text-muted-foreground">Have a referral code? Enter it here</p>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="referralCode">Referral Code</Label>
                  <Input
                    id="referralCode"
                    placeholder="Enter referral code"
                    value={formData.referralCode}
                    onChange={(e) => updateField("referralCode", e.target.value.toUpperCase())}
                    data-testid="input-referral"
                  />
                  <p className="text-xs text-muted-foreground">
                    Skip this step if you don't have a referral code
                  </p>
                </div>

                <div className="bg-primary/10 border border-primary/20 rounded-lg p-4">
                  <div className="flex items-start gap-3">
                    <CheckCircle2 className="w-5 h-5 text-primary mt-0.5" />
                    <div className="text-sm">
                      <p className="font-medium mb-1">Ready to submit!</p>
                      <p className="text-muted-foreground">
                        Your profile will be reviewed by our team. You'll receive a notification 
                        once it's approved or if any changes are needed.
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Navigation Buttons */}
            <div className="flex gap-3 pt-4">
              {step > 1 && (
                <Button
                  variant="outline"
                  onClick={() => setStep(step - 1)}
                  className="flex-1"
                  data-testid="button-back"
                >
                  Back
                </Button>
              )}
              <Button
                onClick={handleNext}
                className="flex-1"
                data-testid="button-next"
              >
                {step === 4 ? "Submit for Review" : "Next"}
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/PendingApproval.tsx.content:
import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ThemeToggle } from "@/components/ThemeToggle";
import { Clock, CheckCircle2, XCircle, Ban, RefreshCw } from "lucide-react";

export default function PendingApproval() {
  const [, setLocation] = useLocation();
  const [approvalStatus, setApprovalStatus] = useState("pending");
  const [rejectionReason, setRejectionReason] = useState("");

  useEffect(() => {
    // Mock: Get approval status from localStorage
    const status = localStorage.getItem("creator_approval_status") || "pending";
    const reason = localStorage.getItem("rejection_reason") || "";
    setApprovalStatus(status);
    setRejectionReason(reason);
  }, []);

  const handleResubmit = () => {
    setLocation("/creator/onboarding");
  };

  const handleLogout = () => {
    localStorage.removeItem("creator_registered");
    localStorage.removeItem("creator_approval_status");
    localStorage.removeItem("rejection_reason");
    setLocation("/creator/login");
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <div className="absolute top-4 right-4">
        <ThemeToggle />
      </div>

      <div className="w-full max-w-md">
        <Card>
          <CardHeader className="text-center space-y-4">
            {approvalStatus === "pending" && (
              <>
                <div className="w-20 h-20 bg-amber-500/10 rounded-full flex items-center justify-center mx-auto">
                  <Clock className="w-10 h-10 text-amber-500" />
                </div>
                <div>
                  <CardTitle className="text-2xl mb-2">Profile Under Review</CardTitle>
                  <Badge variant="secondary" className="bg-amber-500/20 text-amber-700 dark:text-amber-400">
                    Pending Approval
                  </Badge>
                </div>
              </>
            )}

            {approvalStatus === "approved" && (
              <>
                <div className="w-20 h-20 bg-green-500/10 rounded-full flex items-center justify-center mx-auto">
                  <CheckCircle2 className="w-10 h-10 text-green-500" />
                </div>
                <div>
                  <CardTitle className="text-2xl mb-2">Profile Approved!</CardTitle>
                  <Badge className="bg-green-500">Approved</Badge>
                </div>
              </>
            )}

            {approvalStatus === "rejected" && (
              <>
                <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mx-auto">
                  <XCircle className="w-10 h-10 text-red-500" />
                </div>
                <div>
                  <CardTitle className="text-2xl mb-2">Profile Rejected</CardTitle>
                  <Badge variant="destructive">Rejected</Badge>
                </div>
              </>
            )}

            {approvalStatus === "banned" && (
              <>
                <div className="w-20 h-20 bg-destructive/10 rounded-full flex items-center justify-center mx-auto">
                  <Ban className="w-10 h-10 text-destructive" />
                </div>
                <div>
                  <CardTitle className="text-2xl mb-2">Account Banned</CardTitle>
                  <Badge variant="destructive">Banned</Badge>
                </div>
              </>
            )}
          </CardHeader>

          <CardContent className="space-y-6">
            {approvalStatus === "pending" && (
              <div className="text-center space-y-4">
                <p className="text-muted-foreground">
                  Thank you for submitting your profile! Our admin team is currently reviewing your documents.
                </p>
                <div className="bg-primary/10 border border-primary/20 rounded-lg p-4">
                  <p className="text-sm font-medium mb-1">What happens next?</p>
                  <ul className="text-sm text-muted-foreground space-y-1 text-left list-disc list-inside">
                    <li>Admin reviews your documents</li>
                    <li>Verification typically takes 24-48 hours</li>
                    <li>You'll be notified via SMS once approved</li>
                  </ul>
                </div>
              </div>
            )}

            {approvalStatus === "approved" && (
              <div className="text-center space-y-4">
                <p className="text-muted-foreground">
                  Congratulations! Your profile has been approved. You can now start earning on LINKY.
                </p>
                <Button
                  className="w-full"
                  onClick={() => setLocation("/creator")}
                  data-testid="button-go-to-dashboard"
                >
                  Go to Dashboard
                </Button>
              </div>
            )}

            {approvalStatus === "rejected" && (
              <div className="space-y-4">
                <div className="bg-destructive/10 border border-destructive/20 rounded-lg p-4">
                  <p className="text-sm font-semibold mb-2">Rejection Reason:</p>
                  <p className="text-sm text-muted-foreground">
                    {rejectionReason || "Your documents could not be verified. Please check the details and resubmit."}
                  </p>
                </div>
                <p className="text-sm text-muted-foreground text-center">
                  Please correct the issues mentioned above and resubmit your profile for review.
                </p>
                <div className="flex gap-3">
                  <Button
                    variant="outline"
                    onClick={handleLogout}
                    className="flex-1"
                    data-testid="button-logout"
                  >
                    Logout
                  </Button>
                  <Button
                    onClick={handleResubmit}
                    className="flex-1"
                    data-testid="button-resubmit"
                  >
                    <RefreshCw className="w-4 h-4 mr-2" />
                    Resubmit
                  </Button>
                </div>
              </div>
            )}

            {approvalStatus === "banned" && (
              <div className="space-y-4">
                <div className="bg-destructive/10 border border-destructive/20 rounded-lg p-4">
                  <p className="text-sm font-semibold mb-2">Account Status:</p>
                  <p className="text-sm text-muted-foreground">
                    Your account has been permanently banned due to policy violations. 
                    You cannot register again with this mobile number.
                  </p>
                </div>
                <p className="text-sm text-muted-foreground text-center">
                  For more information, please contact our support team.
                </p>
                <Button
                  variant="outline"
                  onClick={handleLogout}
                  className="w-full"
                  data-testid="button-logout"
                >
                  Logout
                </Button>
              </div>
            )}

            {approvalStatus === "pending" && (
              <Button
                variant="outline"
                onClick={handleLogout}
                className="w-full"
                data-testid="button-logout"
              >
                Logout
              </Button>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

