      id: "netbanking",
      name: "Net Banking",
      description: "Pay via your bank account",
      icon: Building2,
      color: "text-purple-600 dark:text-purple-400",
    },
  ];

  const handleSelectMethod = (method: string) => {
    toast({
      title: "Processing Payment",
      description: `Redirecting to ${paymentMethods.find(m => m.id === method)?.name} for ₹${rechargeAmount}...`,
    });

    setTimeout(() => {
